            bool isValid = getTextDataModel(msgFile, rankStrID, out textData);
            if (isValid)
                CheckTagSet(msgFile, textData, rankStrID);

            textData.ApplyFormat();
            msgFile.ClearWordParam();
            return textData;
        }
		private global::Dpr.Message.MessageTextParseDataModel mkstr_set_rank_limit(global::Dpr.Message.MessageMsgFile msgFile, int strID, int[] args) {
            MessageTextParseDataModel textData = null;

