		private global::Dpr.Battle.Logic.BattleStr.SetStrFormat get_strFormat(byte pokeID) {
            if (isIgnoreStrFormat(pokeID))
                return SetStrFormat.MINE;

            if (mainModule.GetRule() == BtlRule.BTL_RULE_RAID)
                return (mainModule.PokeIDtoPokePos(pokeCon, pokeID) == BtlPokePos.POS_RAID_BOSS) ? SetStrFormat.MINE : SetStrFormat.TRAINER;

            if (!mainModule.IsOpponentClientID((byte)clientID, MainModule.PokeIDtoClientID(pokeID)))
                return SetStrFormat.MINE;

            return (mainModule.GetCompetitor(true) == BtlCompetitor.BTL_COMPETITOR_WILD) ? SetStrFormat.WILD : SetStrFormat.ENEMY;
        }
		private bool isIgnoreStrFormat(byte pokeID) {
            if (fIgnoreFormat)
                return true;

            if (mainModule.GetCompetitor(true) == BtlCompetitor.BTL_COMPETITOR_WILD &&
                mainModule.IsOpponentClientID((byte)clientID, MainModule.PokeIDtoClientID(pokeID)))
            {
                MonsNo monsno = (MonsNo)pokeCon.GetPokeParamConst(pokeID).GetMonsNo();
                if (PokeRegulation.CheckLegend(monsno) || PokeRegulation.CheckSubLegend(monsno))
                    return true;
            }

            return false;
        }
		private int get_setStrID(byte pokeID, int defaultStrID) {
            return defaultStrID + (int)get_strFormat(pokeID);
        }
		private int get_setStrID_Poke2(byte pokeID1, byte pokeID2, int defaultStrID) {
            SetStrFormat format1 = get_strFormat(pokeID1);
            switch (format1)
            {
                case SetStrFormat.MINE:
                    return (ushort)(defaultStrID + (int)get_strFormat(pokeID2));
                case SetStrFormat.WILD:
                    defaultStrID += 4;
                    break;
                case SetStrFormat.ENEMY:
                    defaultStrID += 6;
                    break;
                case SetStrFormat.TRAINER:
                    defaultStrID += 8;
                    break;
            }

            if (get_strFormat(pokeID2) == format1)
                defaultStrID++;

            return defaultStrID;
        }
		private int get_setPtnStrID(byte pokeID, int originStrID, byte ptnNum) {
            return originStrID + ptnNum * 4 + (int)get_strFormat(pokeID);
        }
		private int searchPokeTagCount(global::Dpr.Message.MessageMsgFile msgFile, int strID)
		{
			getTextDataModel(msgFile, strID, out MessageTextParseDataModel textData);
			int count = 0;
			for (int i = 0; i < textData.TagDataList.Count; i++)
			{
				MessageTagDataModel tag = textData.TagDataList[i];
				if (tag.patternId == MessageEnumData.TagPatternID.Word)
				{
					switch (tag.tagId)
					{
						case (int)MessageEnumData.NameID.PokemonName:
						case (int)MessageEnumData.NameID.PokemonNickname:
						case (int)MessageEnumData.NameID.PokemonNicknameTwo:
						case (int)MessageEnumData.NameID.AnotherName:
							count++;
							break;
					}
				}
			}
			return count;
		}
		public global::Dpr.Message.MessageTextParseDataModel MakeStringWaza(byte pokeID, ushort waza) {
            return makeStringWaza(pokeID, waza);
        }
		private global::Dpr.Message.MessageTextParseDataModel makeStringWaza(byte pokeID, ushort waza) {
            MessageMsgFile msgFile = GetMsgFile(MsgSrcID.ATK);
            SetStrFormat strFormat = get_strFormat(pokeID);

            string label;
            switch (strFormat)
            {
                case SetStrFormat.WILD:
                    label = string.Format("ATKMSG_Y_{0:d3}", waza);
                    break;
                case SetStrFormat.ENEMY:
                    label = string.Format("ATKMSG_E_{0:d3}", waza);
                    break;
                case SetStrFormat.TRAINER:
                    label = string.Format("ATKMSG_T_{0:d3}", waza);
                    break;
                default:
                    label = string.Format("ATKMSG_M_{0:d3}", waza);
                    break;
            }

            register_PokeNickname(msgFile, pokeID, BUFIDX_POKE_1ST);
            if (mainModule != null)
                register_TrainerName(msgFile, BUFIDX_TRAINER_NAME_1ST, MainModule.PokeIDtoClientID(pokeID));

            MessageTextParseDataModel textData = msgFile.GetTextDataModel(label);
            if (textData == null)
            {
                switch (strFormat)
                {
                    case SetStrFormat.MINE:
                        label = "ATKMSG_M_000";
                        break;
                    case SetStrFormat.WILD:
                        label = "ATKMSG_Y_000";
                        break;
                    case SetStrFormat.ENEMY:
                        label = "ATKMSG_E_000";
                        break;
                    case SetStrFormat.TRAINER:
                        label = "ATKMSG_T_000";
                        break;
                }
                textData = msgFile.GetTextDataModel(label);
            }

            textData.ApplyFormat();
            msgFile.ClearWordParam();
            return textData;
        }
