		private void CheckTagSet(global::Dpr.Message.MessageMsgFile msgFile, global::Dpr.Message.MessageTextParseDataModel textData, int strID) {
            MsgSrcID srcID = GetMsgSrcID(msgFile);
            string label = "";
            switch (srcID)
            {
                case MsgSrcID.STD:
                    label = BTL_STRID_STD.LABEL[strID];
                    break;
                case MsgSrcID.SET:
                    label = BTL_STRID_SET.LABEL[strID];
                    break;
            }

            foreach (MessageTagDataModel tag in textData.TagDataList)
            {
                if (!tag.IsAssignmentTag || msgFile.IsSetWordParam(tag.index))
                    continue;

                checkTagSb.AppendLine(string.Format("{0}: strID = [{1}]{2}, tagIndex = {3} is null.", srcID, strID, label, tag.index));
            }

            if (checkTagSb.Length != 0)
                checkTagSb.Clear();
        }
		private bool getTextDataModel(global::Dpr.Message.MessageMsgFile msgFile, int strID, out global::Dpr.Message.MessageTextParseDataModel outTextData)
		{
			MessageTextParseDataModel textData;
			switch (GetMsgSrcID(msgFile))
			{
				case MsgSrcID.STD:
					textData = msgFile.GetTextDataModel(BTL_STRID_STD.LABEL[strID]);
					break;
				case MsgSrcID.SET:
					textData = msgFile.GetTextDataModel(BTL_STRID_SET.LABEL[strID]);
					break;
				default:
					textData = msgFile.GetTextDataModelByIndex(strID);
					break;
			}
			if (textData == null || textData.IsLabelNull)
			{
				outTextData = _msgFiles[0].GetTextDataModelByIndex(0);
				return false;
			}
			outTextData = textData;
			return true;
		}
		private global::Dpr.Battle.Logic.BattleStr.MsgSrcID GetMsgSrcID(global::Dpr.Message.MessageMsgFile msgFile) {
            for (int i = 0; i < _msgFiles.Length; i++)
            {
                if (_msgFiles[i] == msgFile)
                    return (MsgSrcID)i;
            }
            return MsgSrcID.MAX;
        }
		public static string MakeText(global::Dpr.Message.MessageTextParseDataModel textData) {
            if (textSb.Length <= 0)
            {
                MessageTextLineDataModel[] lines = textData.GetLineMessageDataArray();
                for (int i = 0; i < lines.Length; i++)
                    textSb.Append(lines[i].GetText());
            }

            string text = textSb.ToString();
            textSb.Clear();
            return text;
        }
